insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('queso-pera', 'Queso pera', array['queso de pera', 'queso hilado']::text[], 'lacteos', 'Queso de pasta hilada; valores de mozzarella de leche entera, USDA sr_legacy · 170845', '{"azucar_g": 0, "b12_ug": 2.28, "b1_mg": 0.03, "b2_mg": 0.28, "b3_mg": 0.1, "b6_mg": 0.04, "calcio_mg": 505, "carbos_g": 2.4, "cobre_mg": 0.01, "colesterol_mg": 79, "fibra_g": 0, "folato_ug": 7, "fosforo_mg": 354, "grasa_g": 22.14, "grasa_sat_g": 13.9, "hierro_mg": 0.44, "kcal": 299, "magnesio_mg": 20, "manganeso_mg": 0.03, "potasio_mg": 76, "proteina_g": 22.17, "selenio_ug": 17, "sodio_mg": 486, "vit_a_ug": 179, "vit_c_mg": 0, "vit_d_ug": 0.4, "vit_e_mg": 0.19, "vit_k_ug": 2.3, "zinc_mg": 2.92}'::jsonb, '{"texto": "1 tajada", "gramos": 30}'::jsonb, '[{"texto": "1 tajada", "gramos": 30}, {"texto": "1 porción", "gramos": 60}, {"texto": "100 g", "gramos": 100}]'::jsonb, null, 'queso pera queso de pera queso hilado') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, categoria = excluded.categoria, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('huevos-revueltos', 'Huevos revueltos', array['huevo revuelto', 'huevos batidos']::text[], 'proteinas', 'El huevo solo, cocido sin grasa: el aceite, la mantequilla o el aceite de oliva se escogen en Añadidos. USDA sr_legacy · 171287', '{"azucar_g": 0.37, "b12_ug": 0.89, "b1_mg": 0.04, "b2_mg": 0.46, "b3_mg": 0.08, "b6_mg": 0.17, "calcio_mg": 56, "carbos_g": 0.72, "cobre_mg": 0.07, "colesterol_mg": 372, "fibra_g": 0, "folato_ug": 47, "fosforo_mg": 198, "grasa_g": 9.51, "grasa_sat_g": 3.13, "hierro_mg": 1.75, "kcal": 143, "magnesio_mg": 12, "manganeso_mg": 0.03, "potasio_mg": 138, "proteina_g": 12.56, "selenio_ug": 30.7, "sodio_mg": 142, "vit_a_ug": 160, "vit_c_mg": 0, "vit_d_ug": 2, "vit_e_mg": 1.05, "vit_k_ug": 0.3, "zinc_mg": 1.29}'::jsonb, '{"texto": "1 huevo", "gramos": 50}'::jsonb, '[{"texto": "1 huevo", "gramos": 50}, {"texto": "2 huevos", "gramos": 100}, {"texto": "3 huevos", "gramos": 150}]'::jsonb, null, 'huevos revueltos huevo revuelto huevos batidos') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, categoria = excluded.categoria, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
